   check(editor.isShowing()&&t.expenses.contains(bill),"failed delete rolls back and keeps editor",count);
   in.runOnMainSync(()->{a.loadFailed=false;editor.getButton(AlertDialog.BUTTON_NEUTRAL).performClick();});in.waitForIdleSync();AuditHostUiTest.click(in,"确定");in.waitForIdleSync();
   check(!editor.isShowing()&&!t.expenses.contains(bill),"successful delete dismisses editor",count);
