 private static void check(boolean ok,String label,int[] n){if(!ok)throw new AssertionError(label);n[0]++;}
 private static EditText firstEdit(android.view.View v){if(v instanceof EditText)return (EditText)v;if(v instanceof android.view.ViewGroup){android.view.ViewGroup g=(android.view.ViewGroup)v;for(int i=0;i<g.getChildCount();i++){EditText e=firstEdit(g.getChildAt(i));if(e!=null)return e;}}return null;}
 private static Object field(Object owner,String name)throws Exception{java.lang.reflect.Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(owner);}
 private static Object uncheckedField(Object owner,String name){try{return field(owner,name);}catch(Exception e){throw new AssertionError(e);}}
 private static void setFirstEditable(Instrumentation in,String value){android.view.accessibility.AccessibilityNodeInfo node=null;long deadline=android.os.SystemClock.uptimeMillis()+4000;while(node==null&&android.os.SystemClock.uptimeMillis()<deadline){in.waitForIdleSync();node=editable(in.getUiAutomation().getRootInActiveWindow());if(node==null)android.os.SystemClock.sleep(50);}if(node==null)throw new AssertionError("member name field missing");Bundle b=new Bundle();b.putCharSequence(android.view.accessibility.AccessibilityNodeInfo.ACTION_ARGUMENT_SET_TEXT_CHARSEQUENCE,value);if(!node.performAction(android.view.accessibility.AccessibilityNodeInfo.ACTION_SET_TEXT,b))throw new AssertionError("member name not set");}
 private static android.view.accessibility.AccessibilityNodeInfo editable(android.view.accessibility.AccessibilityNodeInfo n){if(n==null)return null;if(n.isEditable())return n;for(int i=0;i<n.getChildCount();i++){android.view.accessibility.AccessibilityNodeInfo child=editable(n.getChild(i));if(child!=null)return child;}return null;}
